import streamlit as st
import anthropic

st.set_page_config(
    page_title="మన జీవితాలు - Krishnamurti AI",
    page_icon="🪔",
    layout="centered"
)

BOOK_PAGES = {
    "25": "",
    "65": "",
    "105": "",
    "145": "",
    "185": "",
    "225": "",
    "265": "",
    "285": "",
}

st.markdown("""
<style>
    .main-title { font-size: 2rem; font-weight: 600; color: #8B4513; text-align: center; }
    .sub-title { font-size: 1rem; color: #A0522D; text-align: center; margin-bottom: 1.5rem; }
    .answer-box { background: #FFF8F0; border-left: 4px solid #D2691E; padding: 1.2rem 1.5rem;
                  border-radius: 8px; line-height: 1.9; font-size: 1.05rem; color: #3E2010; }
    .cost-note { font-size: 0.75rem; color: #999; text-align: center; margin-top: 0.5rem; }
    .footer-note { font-size: 0.75rem; color: #999; text-align: center; margin-top: 2rem; }
    .login-box { max-width: 360px; margin: 4rem auto; padding: 2rem;
                 border: 1px solid #D2691E33; border-radius: 12px;
                 background: #FFF8F0; text-align: center; }
    .login-title { font-size: 1.5rem; color: #8B4513; margin-bottom: 0.5rem; }
    .login-sub { font-size: 0.9rem; color: #A0522D; margin-bottom: 1.5rem; }
</style>
""", unsafe_allow_html=True)

# ── Login gate ──────────────────────────────────────────────
def check_password():
    if st.session_state.get("authenticated"):
        return True

    st.markdown('<div class="login-box">', unsafe_allow_html=True)
    st.markdown('<div class="login-title">🪔 మన జీవితాలు</div>', unsafe_allow_html=True)
    st.markdown('<div class="login-sub">జిడ్డు కృష్ణమూర్తి వ్యాఖ్యానాలు</div>', unsafe_allow_html=True)
    st.markdown("**పాస్‌వర్డ్ నమోదు చేయండి** / Enter password to continue")
    pwd = st.text_input("", type="password", placeholder="Password", label_visibility="collapsed")
    if st.button("లోపలికి వెళ్ళండి / Enter", use_container_width=True, type="primary"):
        if pwd == st.secrets["APP_PASSWORD"]:
            st.session_state["authenticated"] = True
            st.rerun()
        else:
            st.error("తప్పు పాస్‌వర్డ్ / Incorrect password")
    st.markdown('</div>', unsafe_allow_html=True)
    return False

if not check_password():
    st.stop()
# ────────────────────────────────────────────────────────────

st.markdown('<div class="main-title">🪔 మన జీవితాలు</div>', unsafe_allow_html=True)
st.markdown('<div class="sub-title">జిడ్డు కృష్ణమూర్తి వ్యాఖ్యానాలు • AI సహాయకుడు</div>', unsafe_allow_html=True)

lang = st.radio("భాష / Language", ["తెలుగు", "English"], horizontal=True)

suggestions_te = [
    "జీవితంలో నిజమైన సంతోషం ఎలా పొందాలి?",
    "అహంకారం గురించి కృష్ణమూర్తి ఏమి చెప్పారు?",
    "భయాన్ని అధిగమించడం ఎలా?",
    "మనసు యొక్క స్వభావం ఏమిటి?",
    "సంబంధాల గురించి కృష్ణమూర్తి అభిప్రాయం ఏమిటి?",
    "ధ్యానం అంటే ఏమిటి?",
]
suggestions_en = [
    "What does Krishnamurti say about happiness?",
    "How to overcome fear according to the book?",
    "What is the nature of the mind?",
    "What does the book say about ego?",
    "What is Krishnamurti\'s view on relationships?",
    "What does the book say about meditation?",
]

is_telugu = lang == "తెలుగు"
suggestions = suggestions_te if is_telugu else suggestions_en

st.markdown("#### సూచించిన ప్రశ్నలు" if is_telugu else "#### Suggested Questions")
cols = st.columns(2)
selected_suggestion = None
for i, s in enumerate(suggestions):
    if cols[i % 2].button(s, use_container_width=True):
        selected_suggestion = s

st.markdown("---")
placeholder = "మీ ప్రశ్న ఇక్కడ టైప్ చేయండి..." if is_telugu else "Type your question here..."
user_question = st.text_area("", placeholder=placeholder, height=80, label_visibility="collapsed")

btn_label = "అడగండి ➤" if is_telugu else "Ask ➤"
ask_clicked = st.button(btn_label, type="primary", use_container_width=True)

final_question = selected_suggestion or (user_question.strip() if ask_clicked else None)

if final_question:
    with st.spinner("పుస్తకం చదువుతున్నాను..." if is_telugu else "Reading the book..."):
        try:
            client = anthropic.Anthropic(api_key=st.secrets["ANTHROPIC_API_KEY"])

            # Build image blocks WITH prompt caching on each image
            # This caches the 8 page images after first request — saves ~80% input cost
            image_blocks = []
            page_items = list(BOOK_PAGES.items())
            for i, (page_num, b64_data) in enumerate(page_items):
                block = {
                    "type": "image",
                    "source": {
                        "type": "base64",
                        "media_type": "image/jpeg",
                        "data": b64_data
                    }
                }
                # Add cache_control to the last image block to cache everything before it
                if i == len(page_items) - 1:
                    block["cache_control"] = {"type": "ephemeral"}
                image_blocks.append(block)

            system_prompt = f"""You are an AI guide for the book "మన జీవితాలు" (Mana Jeevithalu) — 
the Telugu translation of "Commentaries on Living, First Series" by Jiddu Krishnamurti.
Translated by Abburi Chaya Devi. Authorized by Krishnamurti Foundation India. 333 pages.

You have been provided with 8 sampled pages (25, 65, 105, 145, 185, 225, 265, 285) from this book.
Read the Telugu text carefully in these pages and use it to answer questions.

Key themes: freedom from conditioning, self-observation without judgment, nature of mind,
fear, desire, loneliness, death, meditation, truth, beauty, relationship.

Instructions:
- {"ALWAYS respond entirely in Telugu (తెలుగు). Write in natural, readable Telugu." if is_telugu else "Respond in clear, thoughtful English."}
- Be true to Krishnamurti\'s inquiry-based, non-dogmatic style
- Reference specific passages from the pages when possible
- Keep answers focused and insightful (3-5 paragraphs)"""

            message = client.messages.create(
                model="claude-haiku-4-5-20251001",  # Haiku: 3x cheaper than Sonnet
                max_tokens=1024,
                system=[
                    {
                        "type": "text",
                        "text": system_prompt,
                        "cache_control": {"type": "ephemeral"}  # Cache system prompt too
                    }
                ],
                messages=[{
                    "role": "user",
                    "content": image_blocks + [{"type": "text", "text": final_question}]
                }]
            )

            answer = message.content[0].text

            # Show cache savings info
            usage = message.usage
            cache_read = getattr(usage, "cache_read_input_tokens", 0)
            cache_created = getattr(usage, "cache_creation_input_tokens", 0)
            input_tokens = usage.input_tokens
            output_tokens = usage.output_tokens

            # Cost calculation (Haiku: $1/M input, $5/M output, $0.10/M cache read)
            if cache_read > 0:
                cost = (cache_read * 0.10 + input_tokens * 1.0 + output_tokens * 5.0) / 1_000_000
                saved = (cache_read * 1.0 - cache_read * 0.10) / 1_000_000
                cache_msg = f"💰 Cost: ~${cost:.4f} | Cache saved: ~${saved:.4f} (pages were cached!)"
            else:
                cost = (input_tokens * 1.0 + output_tokens * 5.0) / 1_000_000
                cache_msg = f"💰 Cost: ~${cost:.4f} | Pages cached for next request (will be cheaper!)"

            st.markdown(f'<div class="answer-box">{answer}</div>', unsafe_allow_html=True)
            st.markdown(f'<div class="cost-note">{cache_msg}</div>', unsafe_allow_html=True)

        except Exception as e:
            st.error(f"Error: {str(e)}")

st.markdown(
    '<div class="footer-note">మన జీవితాలు &#169; 1997 Krishnamurti Foundation India &#8226; 8 sampled pages used as reference &#8226; Powered by Claude Haiku + Prompt Caching</div>',
    unsafe_allow_html=True
)
